const rows = Array.isArray($json) ? $json : ($json.body || []);
const brief = rows[0];
if (!brief || brief.status !== 'approved') return [];
const urls = Array.isArray(brief.source_urls) ? brief.source_urls.filter(value => { const url = typeof value === 'string' ? value : value?.url; return typeof url === 'string' && /^https:\/\//i.test(url); }) : [];
if (urls.length < 2) throw new Error('Approved briefs require at least two HTTPS source URLs before drafting.');
const unsafe = /ignore (all|previous)|system message|developer message|reveal.*prompt/i.test(JSON.stringify(brief));
if (unsafe) throw new Error('Prompt-like instructions detected in brief.');
return [{ json: { brief: { ...brief, source_urls: urls }, dry_run: $execution.mode === 'manual' } }];

const sources = $input.all().map((item, index) => {
  const url = $node['Split Approved Sources'].all()[index]?.json.url || '';
  const html = String(item.json.body ?? item.json.data ?? item.json).slice(0, 40000);
  const text = html.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 16000);
  return { url, text };
});
if (sources.length < 2 || sources.some(source => !source.url || source.text.length < 300)) throw new Error('Two usable downloaded sources are required.');
const unsafe = /ignore (all|previous)|system message|developer message|reveal.*prompt/i.test(JSON.stringify(sources));
if (unsafe) throw new Error('Prompt injection pattern detected in source material.');
return [{ json: { brief: $node['Validate Brief'].json.brief, sources } }];

