const match = String($json.output || '').match(/\{[\s\S]*\}/);
if (!match) throw new Error('Evidence model returned no JSON.');
const sheet = JSON.parse(match[0]);
const approved = new Set($node['Build Untrusted Source Packet'].json.sources.map(source => source.url));
const sources = Array.isArray(sheet.sources) ? sheet.sources.filter(source => approved.has(source.url)) : [];
const claims = Array.isArray(sheet.claims) ? sheet.claims : [];
if (sheet.reject || sources.length < 2 || !claims.length || claims.some(claim => !approved.has(claim.source_url) || !claim.claim || !claim.evidence_paraphrase)) throw new Error('Evidence sheet failed source and claim validation.');
if (/ignore (all|previous)|system message|developer message|reveal.*prompt/i.test(JSON.stringify(sheet))) throw new Error('Prompt injection survived evidence validation.');
return [{ json: { brief: $node['Validate Brief'].json.brief, evidence: { ...sheet, sources } } }];

const match = String($json.output || '').match(/\{[\s\S]*\}/);
if (!match) throw new Error('Draft model returned no JSON.');
const draft = JSON.parse(match[0]);
if (!/^[0-9a-f-]{36}$/i.test(draft.translation_group_id || '') || !draft.en || !draft.es || !draft.distribution) throw new Error('Missing localized draft output.');
const required = ['slug','title','meta_title','meta_description','excerpt','content','hero_image_alt','category','primary_keyword','source_urls','related_service_slug'];
const posts = ['en','es'].map(locale => { const value = draft[locale]; if (required.some(key => !value[key]) || !Array.isArray(value.source_urls) || value.source_urls.length < 2) throw new Error('Incomplete ' + locale + ' draft.'); return { ...value, locale, translation_group_id: draft.translation_group_id, hero_image_url: null, status: 'draft', published_at: null }; });
const distribution = ['en','es'].flatMap(locale => ['linkedin','x'].map(channel => ({ translation_group_id: draft.translation_group_id, locale, channel, content: String(draft.distribution?.[locale]?.[channel] || '').trim(), status: 'draft' })));
if (distribution.some(item => !item.content)) throw new Error('Missing social distribution draft.');
return [{ json: { posts, distribution, translation_group_id: draft.translation_group_id, brief_id: $node['Validate Brief'].json.brief.id } }];
